package org.novasos.healthysv2.pharmacy;
import static org.novasos.healthysv2.pharmacy.api.PharmacyDtos.*;import java.math.*;import java.time.*;import java.util.*;import org.novasos.healthysv2.patient.PatientAccessService;import org.novasos.healthysv2.shared.api.dto.PageResponse;import org.novasos.healthysv2.shared.api.error.*;import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service@Transactional class PharmacyService{
 private final PrescriptionRepository prescriptions;private final MedicationStockRepository stocks;private final JdbcTemplate jdbc;private final PatientAccessService access;PharmacyService(PrescriptionRepository prescriptions,MedicationStockRepository stocks,JdbcTemplate jdbc,PatientAccessService access){this.prescriptions=prescriptions;this.stocks=stocks;this.jdbc=jdbc;this.access=access;}
 PrescriptionResponse create(CreatePrescriptionRequest r){access.requireAccess(r.patientId(),"PRESCRIPTIONS","WRITE");validatePrescription(r);var p=Prescription.create(r.patientId(),r.consultationId(),r.prescriberId(),r.organizationId(),r.expiresAt());for(var item:r.items())p.addItem(item.medicationCatalogId(),item.dosage(),item.frequency(),item.route(),item.duration(),item.quantity(),item.instructions());prescriptions.saveAndFlush(p);audit(p,"CREATE_PRESCRIPTION");return response(p);}
 @Transactional(readOnly=true)PrescriptionResponse find(UUID id){var p=get(id);access.requireAccess(p.getPatientId(),"PRESCRIPTIONS","READ");return response(p);}@Transactional(readOnly=true)PageResponse<PrescriptionSummary>search(UUID patient,UUID organization,String status,Pageable pageable){if(patient!=null)access.requireAccess(patient,"PRESCRIPTIONS","READ");return PageResponse.from(prescriptions.search(patient,organization,normalize(status),pageable).map(this::summary));}
 PrescriptionResponse cancel(UUID id){var p=write(id);try{p.cancel();prescriptions.flush();audit(p,"CANCEL_PRESCRIPTION");return response(p);}catch(IllegalStateException e){throw rule("PRESCRIPTION_CANNOT_CANCEL","error.pharmacy.cannot-cancel");}}
 DispenseResponse dispense(UUID id,CreateDispenseRequest r){var p=write(id);require("organization.organization",r.pharmacyOrganizationId(),"Organization");requirePharmacist(r.pharmacistId(),r.pharmacyOrganizationId());var lines=new ArrayList<Prescription.DispenseLine>();var locked=new ArrayList<StockUse>();for(var line:r.items()){PrescriptionItem item;try{item=p.item(line.prescriptionItemId());}catch(NoSuchElementException e){throw notFound("PrescriptionItem",line.prescriptionItemId());}var stock=stocks.lock(r.pharmacyOrganizationId(),item.getMedicationId(),line.batchNumber()).orElseThrow(()->rule("MEDICATION_STOCK_NOT_FOUND","error.pharmacy.stock-not-found"));if(stock.expired())throw rule("MEDICATION_BATCH_EXPIRED","error.pharmacy.batch-expired");locked.add(new StockUse(stock,line.quantityDispensed()));lines.add(new Prescription.DispenseLine(item.getId(),line.quantityDispensed(),line.batchNumber()));}try{var dispense=p.dispense(r.pharmacyOrganizationId(),r.pharmacistId(),lines);locked.forEach(s->s.stock.consume(s.quantity));prescriptions.flush();audit(p,"DISPENSE");return dispense(dispense);}catch(IllegalArgumentException e){throw rule("INVALID_DISPENSE_QUANTITY","error.pharmacy.dispense-quantity");}catch(IllegalStateException e){throw rule(p.expired()?"PRESCRIPTION_EXPIRED":"INSUFFICIENT_STOCK",p.expired()?"error.pharmacy.expired":"error.pharmacy.insufficient-stock");}}
 MedicationStockResponse replenish(ReplenishStockRequest r){require("organization.organization",r.organizationId(),"Organization");requireMedication(r.medicationCatalogId());if(r.expirationDate()!=null&&r.expirationDate().isBefore(LocalDate.now()))throw rule("MEDICATION_BATCH_EXPIRED","error.pharmacy.batch-expired");var stock=stocks.lock(r.organizationId(),r.medicationCatalogId(),r.batchNumber()).orElse(null);if(stock==null)stock=MedicationStock.create(r.organizationId(),r.medicationCatalogId(),r.batchNumber(),r.quantity(),r.expirationDate());else stock.replenish(r.quantity(),r.expirationDate());stock=stocks.saveAndFlush(stock);auditStock(stock,"REPLENISH_STOCK");return stock(stock);}
 @Transactional(readOnly=true)List<MedicationStockResponse>stock(UUID organization,UUID medication){return stocks.search(organization,medication).stream().map(this::stock).toList();}@Transactional(readOnly=true)List<MedicationCatalogResponse>catalog(String query){String q=query==null?"":query.trim();return jdbc.query("select id,code,name,generic_name,form,strength,atc_code from catalog.medication_catalog where active=true and (?='' or lower(coalesce(code,'')) like lower(?) or lower(name) like lower(?) or lower(coalesce(generic_name,'')) like lower(?)) order by name limit 100",(rs,n)->new MedicationCatalogResponse((UUID)rs.getObject(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7)),q,"%"+q+"%","%"+q+"%","%"+q+"%");}
 private void validatePrescription(CreatePrescriptionRequest r){require("patient.patient",r.patientId(),"Patient");require("professional.professional",r.prescriberId(),"Professional");if(r.organizationId()!=null)require("organization.organization",r.organizationId(),"Organization");if(r.consultationId()!=null&&!exists("select count(*) from consultation.consultation where id=? and patient_id=? and professional_id=?",r.consultationId(),r.patientId(),r.prescriberId()))throw rule("CONSULTATION_PRESCRIPTION_MISMATCH","error.pharmacy.consultation");var seen=new HashSet<UUID>();for(var item:r.items()){requireMedication(item.medicationCatalogId());if(!seen.add(item.medicationCatalogId()))throw new ConflictException("MEDICATION_ALREADY_PRESCRIBED","error.pharmacy.medication-exists");}}
 private void requireMedication(UUID id){if(!exists("select count(*) from catalog.medication_catalog where id=? and active=true",id))throw notFound("MedicationCatalog",id);}private void requirePharmacist(UUID id,UUID org){if(!exists("select count(*) from professional.professional p join professional.professional_assignment a on a.professional_id=p.id where p.id=? and p.professional_type='PHARMACIST' and p.status='ACTIVE' and a.organization_id=? and a.status='ACTIVE' and a.start_date<=current_date and (a.end_date is null or a.end_date>=current_date)",id,org))throw rule("PHARMACIST_NOT_ASSIGNED","error.pharmacy.pharmacist-assignment");}
 private Prescription write(UUID id){var p=get(id);access.requireAccess(p.getPatientId(),"PRESCRIPTIONS","WRITE");if(Set.of("DISPENSED","CANCELLED").contains(p.getStatus()))throw rule("PRESCRIPTION_CLOSED","error.pharmacy.closed");return p;}private Prescription get(UUID id){return prescriptions.findById(id).orElseThrow(()->notFound("Prescription",id));}private void require(String table,UUID id,String resource){if(!exists("select count(*) from "+table+" where id=?",id))throw notFound(resource,id);}private boolean exists(String sql,Object...args){return Objects.requireNonNull(jdbc.queryForObject(sql,Integer.class,args))>0;}private String normalize(String v){return v==null||v.isBlank()?null:v.trim().toUpperCase();}
 private void audit(Prescription p,String action){jdbc.update("insert into audit.audit_log(actor_person_id,organization_id,module,entity_type,entity_id,action,new_value) values (?,?,?,?,?,?,?::jsonb)",actor(),p.getOrganizationId(),"PHARMACY","Prescription",p.getId(),action,"{\"status\":\""+p.getStatus()+"\"}");}private void auditStock(MedicationStock s,String action){jdbc.update("insert into audit.audit_log(actor_person_id,organization_id,module,entity_type,entity_id,action,new_value) values (?,?,?,?,?,?,?::jsonb)",actor(),s.getOrganizationId(),"PHARMACY","MedicationStock",s.getId(),action,"{\"quantity\":"+s.getQuantity()+"}");}private UUID actor(){var a=SecurityContextHolder.getContext().getAuthentication();if(!(a instanceof JwtAuthenticationToken jwt))return null;try{UUID sub=UUID.fromString(jwt.getToken().getSubject());return jdbc.query("select id from identity.person where keycloak_user_id=? or id=? limit 1",rs->rs.next()?(UUID)rs.getObject(1):null,sub,sub);}catch(IllegalArgumentException e){return null;}}
 private PrescriptionSummary summary(Prescription p){return new PrescriptionSummary(p.getId(),p.getNumber(),p.getPatientId(),p.getOrganizationId(),p.getPrescribedAt(),p.getExpiresAt(),p.getStatus());}private PrescriptionResponse response(Prescription p){return new PrescriptionResponse(p.getId(),p.getNumber(),p.getPatientId(),p.getConsultationId(),p.getPrescriberId(),p.getOrganizationId(),p.getPrescribedAt(),p.getExpiresAt(),p.getStatus(),p.getItems().stream().map(i->item(p,i)).toList(),p.getDispenses().stream().map(this::dispense).toList());}private PrescriptionItemResponse item(Prescription p,PrescriptionItem i){String[]m=jdbc.query("select code,name from catalog.medication_catalog where id=?",rs->rs.next()?new String[]{rs.getString(1),rs.getString(2)}:new String[]{null,null},i.getMedicationId());var dispensed=p.dispensed(i.getId());return new PrescriptionItemResponse(i.getId(),i.getMedicationId(),m[0],m[1],i.getDosage(),i.getFrequency(),i.getRoute(),i.getDuration(),i.getQuantity(),dispensed,i.getQuantity().subtract(dispensed),i.getInstructions());}private DispenseResponse dispense(Dispense d){return new DispenseResponse(d.getId(),d.getNumber(),d.getPharmacyOrganizationId(),d.getPharmacistId(),d.getDispensedAt(),d.getStatus(),d.getItems().stream().map(this::dispenseItem).toList());}private DispenseItemResponse dispenseItem(DispenseItem i){return new DispenseItemResponse(i.getId(),i.getPrescriptionItemId(),i.getQuantity(),i.getBatch());}private MedicationStockResponse stock(MedicationStock s){String[]m=jdbc.query("select code,name from catalog.medication_catalog where id=?",rs->rs.next()?new String[]{rs.getString(1),rs.getString(2)}:new String[]{null,null},s.getMedicationId());return new MedicationStockResponse(s.getId(),s.getOrganizationId(),s.getMedicationId(),m[0],m[1],s.getBatch(),s.getQuantity(),s.getExpirationDate(),s.expired());}
 private ResourceNotFoundException notFound(String r,Object id){return new ResourceNotFoundException(r,id);}private BusinessRuleException rule(String code,String key){return new BusinessRuleException(code,key);}private record StockUse(MedicationStock stock,BigDecimal quantity){}
}
